mapper.select:
select SUBJECT_NO as subjectNo, /*科目号*/ To_char(BALANCE_DATE,'yyyy-mm-dd') as valDate, /*计提日期*/ ACCT_SUBJECT_ID as prodId, /*产品代码*/ BOK_BOOKSET.BOOKSET_ID AS booksetId, ACCT_MODE as prodType, /*产品类型*/ O_AMT as feeAmt /*当日累计应付费用*/ from BOK_BALANCE, BOK_BOOKSET where BOK_BALANCE.BOOKSET_ID in
#{item,jdbcType=VARCHAR}
AND BOK_BALANCE.BOOKSET_ID = BOK_BOOKSET.BOOKSET_ID and BALANCE_DATE = #{exeDate,jdbcType=TIMESTAMP} and SUBJECT_NO IN ('22060101','22060201','22070101','22080101','22100101','22110101')

select 
CASH_ID as cashId /*现金流代码*/
from FIN_CASH_INFO																																	
where 1=1

	and FINPROD_ID = #{prodId}


	and CASH_TYPE_2  = #{feeType}

select * from ( select BASE_TYPE baseType, /*基数类型*/ YIELD feeRate , /*生效利率*/ BASIS feeCalcType/*计算基础*/ from FIN_CASH_CALC_RULE where 1=1
and CASH_ID = #{cashId}
and EFF_DATE <= #{exeDate,jdbcType=TIMESTAMP} order by BASE_TYPE desc ) where rownum=1

select * from (select DETAIL_DIST detailDist, BOOKSET_ID AS booksetId, /*账套代码*/ (select b.ACCT_SUBJECT_ID FROM BOK_BOOKSET b where b.BOOKSET_ID = BOK_VAL_TABLE_DATA.BOOKSET_ID ) AS prodId, /*产品代码*/ To_char(VAL_DATE,'yyyy-mm-dd hh:mm:ss') as valDate,/*估值日期*/ nvl(cost, to_number(REGEXP_REPLACE(BOK_VAL_TABLE_DATA.SUBJECT_NAME,'[^0-9|.]',''))) cost from BOK_VAL_TABLE_DATA where 1=1
and BOOKSET_ID = #{prodId}
and VAL_DATE = #{exeDate,jdbcType=TIMESTAMP} and DETAIL_DIST IN ('02','08') ) PIVOT ( MAX(cost) FOR detailDist IN ('02' AS totalProductShare ,/*产品总份额*/ '08' AS netAssetValue /*单位净值*/ ) )
